async def act(page):
    """
    - Attempt to dismiss common overlays.
    - Use the KB helper create_curated_collection_by_search(...) to perform the visible search for 'DeepSeek'.
      If it returns non-empty results, click the bottom search-result article on the resulting page and return the helper's raw result (unmodified).
    - If the helper fails or returns no results, perform a manual accessibility-role-centric search using the visible search widget,
      then click the bottom result.
    """
    import re
    import asyncio

    # Small helper to try clicking any visible close/dismiss buttons that match common patterns
    close_name_patterns = [
        re.compile(r"close|dismiss|dismiss this|close dialog", re.I),
        re.compile(r"^×$|^x$|^✕$", re.I),
        re.compile(r"ok|got it|understand|accept", re.I),
        re.compile(r"close this popup|close popup", re.I),
    ]

    for pat in close_name_patterns:
        try:
            btns = page.get_by_role("button", name=pat)
            try:
                cnt = await btns.count()
            except Exception:
                cnt = 0
            for i in range(cnt):
                try:
                    b = btns.nth(i)
                    if await b.is_visible():
                        await b.click()
                        await asyncio.sleep(0.25)
                        break
                except Exception:
                    continue
        except Exception:
            continue

    # Fallback: press Escape to dismiss any modal
    try:
        await page.keyboard.press("Escape")
        await asyncio.sleep(0.2)
    except Exception:
        pass

    # 1) Try KB helper first (required when available for site search)
    kb_results = None
    try:
        kb_results = await create_curated_collection_by_search(page, "DeepSeek", max_results=0, resolve_links=True)
    except Exception:
        kb_results = None

    # If the helper returned a non-empty list, click the bottom article on the current page and return the helper's raw result.
    if isinstance(kb_results, list) and len(kb_results) > 0:
        try:
            main = page.get_by_role("main")
            try:
                await main.wait_for(timeout=5000)
            except Exception:
                pass

            articles = main.get_by_role("article")
            try:
                art_count = await articles.count()
            except Exception:
                art_count = 0

            if art_count > 0:
                last = articles.nth(art_count - 1)
                # Prefer a link inside the article
                links = last.get_by_role("link")
                try:
                    link_cnt = await links.count()
                except Exception:
                    link_cnt = 0
                if link_cnt > 0:
                    await links.nth(0).click()
                else:
                    # fallback to heading
                    headings = last.get_by_role("heading")
                    try:
                        hcnt = await headings.count()
                    except Exception:
                        hcnt = 0
                    if hcnt > 0:
                        await headings.nth(0).click()
                    else:
                        # last resort: click the article element itself
                        await last.click()
        except Exception:
            # ignore click errors but still return raw KB results
            pass

        return kb_results

    # 2) KB helper returned empty or failed. Perform an explicit manual search using accessibility-role-centric selectors.
    try:
        # Use relative goto to ensure reproducible root state
        await page.goto('/')
    except Exception:
        # ignore navigation errors and continue from current page
        pass

    # Try to locate complementary region and then a search input inside it.
    search_input = None
    complementary = None
    try:
        complementary = page.get_by_role("complementary")
        try:
            # wait briefly for complementary region to appear
            await complementary.wait_for(timeout=1500)
        except Exception:
            pass
    except Exception:
        complementary = None

    # Helper to attempt to find input inside a container locator
    async def find_input_in(container):
        if not container:
            return None
        # attempt searchbox with name containing 'search'
        try:
            locator = container.get_by_role("searchbox", name=re.compile(r"search", re.I))
            if await locator.count() > 0:
                return locator.nth(0)
        except Exception:
            pass
        # fallback to any searchbox
        try:
            locator = container.get_by_role("searchbox")
            if await locator.count() > 0:
                return locator.nth(0)
        except Exception:
            pass
        # fallback to textbox named search
        try:
            locator = container.get_by_role("textbox", name=re.compile(r"search", re.I))
            if await locator.count() > 0:
                return locator.nth(0)
        except Exception:
            pass
        # last fallback to any textbox
        try:
            locator = container.get_by_role("textbox")
            if await locator.count() > 0:
                return locator.nth(0)
        except Exception:
            pass
        return None

    if complementary:
        search_input = await find_input_in(complementary)

    # If not found inside complementary, search globally
    if not search_input:
        try:
            search_input = await find_input_in(page)
        except Exception:
            search_input = None

    if not search_input:
        # If we still don't have a search input, there's no visible search widget to use; return empty list
        return []

    # Fill the input and trigger the search using the preferred trigger inside the same complementary region if possible
    try:
        await search_input.fill("DeepSeek")
    except Exception:
        try:
            await search_input.type("DeepSeek")
        except Exception:
            pass

    triggered = False
    # Prefer clicking a nearby Search button inside the complementary region
    trigger_button = None
    if complementary:
        try:
            btn = complementary.get_by_role("button", name=re.compile(r"search", re.I))
            if await btn.count() > 0:
                trigger_button = btn.nth(0)
        except Exception:
            trigger_button = None
        if not trigger_button:
            try:
                btn_any = complementary.get_by_role("button")
                if await btn_any.count() > 0:
                    trigger_button = btn_any.nth(0)
            except Exception:
                trigger_button = None

    # If we found a trigger button, click it; otherwise press Enter in the input
    try:
        if trigger_button:
            await trigger_button.click()
            triggered = True
        else:
            await search_input.press("Enter")
            triggered = True
    except Exception:
        # As a last resort, try pressing Enter on the page
        try:
            await page.keyboard.press("Enter")
            triggered = True
        except Exception:
            triggered = False

    # Wait for results to render in role="main"
    try:
        main = page.get_by_role("main")
        try:
            await main.wait_for(timeout=5000)
        except Exception:
            # fallback to waiting for network idle if client-side update didn't expose main quickly
            try:
                await page.wait_for_load_state('networkidle')
            except Exception:
                pass
    except Exception:
        # nothing to wait for
        pass

    # Locate articles inside main and click the bottom one
    try:
        main = page.get_by_role("main")
        articles = main.get_by_role("article")
        try:
            count = await articles.count()
        except Exception:
            count = 0
        if count == 0:
            return []
        last = articles.nth(count - 1)

        # Prefer clicking a link inside the article
        links = last.get_by_role("link")
        try:
            lcnt = await links.count()
        except Exception:
            lcnt = 0
        if lcnt > 0:
            await links.nth(0).click()
            # Return a minimal scrape result (titles/urls not extracted via KB helper), empty list to indicate no KB data
            return []

        # fallback to heading
        headings = last.get_by_role("heading")
        try:
            hcnt = await headings.count()
        except Exception:
            hcnt = 0
        if hcnt > 0:
            await headings.nth(0).click()
            return []

        # last resort: click the article container itself
        await last.click()
        return []
    except Exception:
        return []

